566	        String observationDbId = observation.getDbId();
567	        OffsetDateTime lastSyncedTime = observation.getLastSyncedTime();
568	
569	        // Always remove existing trait before inserting again
570	        // Based on plot_id, prevent duplicates
571	        dt.deleteTrait(rangeBox.getPlotID(), parent);
572	
573	        String exp_id = Integer.toString(ep.getInt("SelectedFieldExpId", 0));
574	        dt.insertUserTraits(rangeBox.getPlotID(), parent, trait, value,
575	                ep.getString("FirstName", "") + " " + ep.getString("LastName", ""),
576	                ep.getString("Location", ""), "", exp_id, observationDbId,
577	                lastSyncedTime);
578	    }
