849	    @Override
850	    public boolean dispatchKeyEvent(KeyEvent event) {
851	        int action = event.getAction();
852	        int keyCode = event.getKeyCode();
853	        switch (keyCode) {
854	            case KeyEvent.KEYCODE_VOLUME_UP:
855	                if (ep.getBoolean(GeneralKeys.VOLUME_NAVIGATION, false)) {
856	                    if (action == KeyEvent.ACTION_UP) {
857	                        rangeBox.moveEntryRight();
858	                    }
859	                    return true;
860	                }
861	                return false;
862	            case KeyEvent.KEYCODE_VOLUME_DOWN:
863	                if (ep.getBoolean(GeneralKeys.VOLUME_NAVIGATION, false)) {
864	                    if (action == KeyEvent.ACTION_UP) {
865	                        rangeBox.moveEntryLeft();
866	                    }
867	                    return true;
868	                }
869	                return false;
870	            case KeyEvent.KEYCODE_ENTER:
871	                String return_action = ep.getString(GeneralKeys.RETURN_CHARACTER, "0");
872	
873	                if (return_action.equals("0")) {
874	                    if (action == KeyEvent.ACTION_UP) {
875	                        rangeBox.moveEntryRight();
876	                        return false;
877	                    }
878	                }
879	
880	                if (return_action.equals("1")) {
881	                    if (action == KeyEvent.ACTION_UP) {
882	                        traitBox.moveTrait("right");
883	                        return true;
884	                    }
885	                }
886	
887	                if (return_action.equals("2")) {
888	                    return true;
889	                }
890	
891	                return false;
892	            default:
893	                return super.dispatchKeyEvent(event);
894	        }
895	    }
