897	    protected void onActivityResult(int requestCode, int resultCode, Intent data) {
898	        super.onActivityResult(requestCode, resultCode, data);
899	
900	        switch (requestCode) {
901	            case 1:
902	                if (resultCode == RESULT_OK) {
903	                    String mChosenFileString = data.getStringExtra("result");
904	                    File mChosenFile = new File(mChosenFileString);
905	
906	                    String suffix = mChosenFileString.substring(mChosenFileString.lastIndexOf('.') + 1).toLowerCase();
907	
908	                    String mime = MimeTypeMap.getSingleton().getMimeTypeFromExtension(suffix);
909	                    Intent open = new Intent(Intent.ACTION_VIEW);
910	                    open.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);
911	                    open.setDataAndType(FileProvider.getUriForFile(this, this.getApplicationContext().getPackageName() + ".fileprovider", mChosenFile), mime);
912	
913	                    startActivity(open);
914	                }
915	                break;
916	            case 2:
917	                if (resultCode == RESULT_OK) {
918	                    inputPlotId = data.getStringExtra("result");
919	                    rangeBox.setAllRangeID();
920	                    int[] rangeID = rangeBox.getRangeID();
921	                    moveToSearch("id", rangeID, null, null, inputPlotId);
922	                }
923	                break;
924	            case 252:
925	                if (resultCode == RESULT_OK) {
926	                    PhotoTraitLayout traitPhoto = traitLayouts.getPhotoTrait();
927	                    traitPhoto.makeImage(traitBox.getCurrentTrait(),
928	                            traitBox.getNewTraits());
929	                }
930	                break;
931	        }
932	
933	        IntentResult result = IntentIntegrator.parseActivityResult(requestCode, resultCode, data);
934	        if (result != null) {
935	            inputPlotId = result.getContents();
936	            rangeBox.setAllRangeID();
937	            int[] rangeID = rangeBox.getRangeID();
938	            moveToSearch("id", rangeID, null, null, inputPlotId);
939	        } else {
940	            super.onActivityResult(requestCode, resultCode, data);
941	        }
942	    }
