1751	        private int movePaging(int pos, int step, boolean cyclic) {
1752	            // If ignore existing data is enabled, then skip accordingly
1753	            final SharedPreferences ep = parent.getPreference();
1754	
1755	            if (ep.getBoolean(GeneralKeys.HIDE_ENTRIES_WITH_DATA, false)) {
1756	                if (step == 1 && pos == rangeID.length) {
1757	                    return 1;
1758	                }
1759	
1760	                final int prevPos = pos;
1761	                TraitObject trait = parent.getTraitBox().getCurrentTrait();
1762	                while (true) {
1763	                    pos = moveSimply(pos, step);
1764	                    // absorb the differece
1765	                    // between single click and repeated clicks
1766	                    if (cyclic) {
1767	                        if (pos == prevPos) {
1768	                            return pos;
1769	                        } else if (pos == 1) {
1770	                            pos = rangeID.length;
1771	                        } else if (pos == rangeID.length) {
1772	                            pos = 1;
1773	                        }
1774	                    } else {
1775	                        if (pos == 1 || pos == prevPos) {
1776	                            return pos;
1777	                        }
1778	                    }
1779	
1780	                    if (!parent.existsTrait(rangeID[pos - 1])) {
